import "server-only";
import index from "@/data/sets/index.json";
import me1 from "@/data/sets/me1.json";
import me2 from "@/data/sets/me2.json";
import me2pt5 from "@/data/sets/me2pt5.json";
import sv3pt5 from "@/data/sets/sv3pt5.json";
import sv8pt5 from "@/data/sets/sv8pt5.json";
import { buildPool, cardOdds, rarityOdds, type Card, type DexCard } from "./odds";
import { PACKS, type PackConfig } from "./packs";
import type { Listing } from "./vault";

// Generated by scripts/build-catalog.mjs — rerun it to refresh prices.
const CARDS: Record<string, Card[]> = { me1, me2, me2pt5, sv3pt5, sv8pt5 } as Record<string, Card[]>;

export type SetMeta = (typeof index.sets)[number];

export type PackListing = PackConfig & { set: SetMeta };

export const catalogGeneratedAt = index.generatedAt;

export function listPacks(): PackListing[] {
  return PACKS.flatMap((p) => {
    const set = index.sets.find((s) => s.id === p.setId);
    return set ? [{ ...p, set }] : [];
  });
}

/** Every card that can come out of a listed pack, with its per-pack odds. */
export function listDexCards(): DexCard[] {
  return listPacks().flatMap((p) => {
    const cards = CARDS[p.setId] ?? [];
    const odds = rarityOdds(p, buildPool(cards));
    return cards.map((c) => ({
      id: c.id,
      number: c.number,
      name: c.name,
      rarity: c.rarity,
      supertype: c.supertype,
      price: c.price,
      img: c.img,
      setId: p.setId,
      setName: p.set.name,
      packPrice: p.price,
      odds: cardOdds(c, odds),
    }));
  });
}

const DEMO_SELLERS = ["red.trainer", "misty_holo", "brock.vault", "oaklab", "gary.bnb", "erika-grass", "lt_surge", "sabrina.psy", "blaine.vol", "koga.ninja"];

/** Deterministic hash → [0, 1) so the seeded market is identical on every render. */
const unit = (s: string) => {
  let h = 2166136261;
  for (const ch of s) h = Math.imul(h ^ ch.charCodeAt(0), 16777619);
  return ((h >>> 0) % 10000) / 10000;
};

/**
 * Seeded DEMO listings so the PokéMart isn't empty: mid and high value cards
 * from each pack, asked at 88–118% of market by placeholder sellers.
 */
export function demoListings(): Listing[] {
  return listPacks().flatMap((p) => {
    const pool = (CARDS[p.setId] ?? []).filter((c) => (c.price ?? 0) >= 2.5).sort((a, b) => (b.price ?? 0) - (a.price ?? 0));
    const picks = pool.filter((c, i) => i < 3 || unit(c.id) < 0.22).slice(0, 9);
    return picks.map((c) => {
      const r = unit(`${c.id}:ask`);
      return {
        id: `D-${c.id}`,
        seller: DEMO_SELLERS[Math.floor(unit(`${c.id}:who`) * DEMO_SELLERS.length)],
        price: Math.round((c.price ?? 0) * (0.88 + r * 0.3) * 100) / 100,
        listedAt: Math.floor(unit(`${c.id}:when`) * 72),
        demo: true,
        cardId: c.id,
        setId: p.setId,
        setName: p.set.name,
        name: c.name,
        number: c.number,
        rarity: c.rarity,
        reverse: false,
        value: c.price ?? 0,
        img: c.img,
      };
    });
  });
}

export function getPack(setId: string) {
  const listing = listPacks().find((p) => p.setId === setId);
  if (!listing) return null;
  return { listing, cards: CARDS[setId] ?? [] };
}
